document.addEventListener("DOMContentLoaded",()=>{const e=new URLSearchParams(window.location.search),o=e.get("q")||"";if(o){const e=new URLSearchParams({q:o}).toString();window.open("https://www.google.com/search?"+e,"_self"),window.open("https://search.brave.com/search?"+e,"_blank"),window.open("https://duckduckgo.com/?"+e+"&ia=web","_blank"),window.open("https://www.bing.com/search?"+e+"&form=QBLH","_blank"),window.open("https://www.startpage.com/sp/search?query="+e,"_blank"),window.open("https://www.ecosia.org/search?"+e,"_blank")}else;});